#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

void emit(int32_t v);
void emitu(uint32_t v);
uint32_t input_len(void);
uint8_t input_byte(uint32_t i);

int main(void) {
    // Ring buffer with capacity 8
    uint8_t buffer[8];
    uint32_t head = 0;      // index where next push goes
    uint32_t tail = 0;      // index where next pop comes from
    uint32_t count = 0;     // number of elements in queue

    uint32_t len = input_len();

    for (uint32_t i = 0; i < len; i++) {
        uint8_t cmd = input_byte(i);

        if (cmd < 0x80) {
            // Push command
            if (count >= 8) {
                // Queue is full
                emit(-1);
            } else {
                // Add to queue
                buffer[head] = cmd;
                head = (head + 1) % 8;
                count++;
                // Print nothing for successful push
            }
        } else {
            // Pop command
            if (count == 0) {
                // Queue is empty
                emit(-2);
            } else {
                // Remove from queue
                uint8_t val = buffer[tail];
                tail = (tail + 1) % 8;
                count--;
                emit((int32_t)val);
            }
        }
    }

    // Print the number of values left in the queue
    emit((int32_t)count);

    return 0;
}

