    if (rb->count >= RINGBUF_CAPACITY) {
        return false;
    }
    rb->buf[rb->tail] = value;
    rb->tail = (rb->tail + 1) % RINGBUF_CAPACITY;
    rb->count++;
    return true;
}

bool ringbuf_pop(ringbuf_t *rb, uint8_t *value) {
    if (rb->count == 0) {
        return false;
    }
    *value = rb->buf[rb->head];
    rb->head = (rb->head + 1) % RINGBUF_CAPACITY;
    rb->count--;
    return true;
}

