#define CTRL_REG_ADDR 0x10370000

int main(void) {
    volatile uint32_t *ctrl_reg = (volatile uint32_t *)CTRL_REG_ADDR;

    // Write 0 to the register
    *ctrl_reg = 0;

    uint32_t len = input_len();

    // Process pairs of bytes
    for (uint32_t i = 0; i + 1 < len; i += 2) {
        uint8_t field = input_byte(i);
        uint8_t value = input_byte(i + 1);

        uint32_t current = *ctrl_reg;
        uint32_t new_val = current;
        bool valid = true;

        switch (field) {
            case 0: // EN (bit 0)
                if (value > 1) {
                    valid = false;
                } else {
                    new_val = (current & ~(1U << 0)) | ((uint32_t)value << 0);
                }
                break;
            case 1: // MODE (bits 4-5)
                if (value > 3) {
                    valid = false;
                } else {
                    new_val = (current & ~(3U << 4)) | ((uint32_t)value << 4);
                }
                break;
            case 2: // DIV (bits 8-19), store value * 16
            {
                uint32_t div_val = (uint32_t)value * 16;
                if (div_val > 0xFFF) { // 12 bits max
                    valid = false;
                } else {
                    new_val = (current & ~(0xFFFU << 8)) | (div_val << 8);
                }
                break;
            }
            case 3: // IRQ (bit 31)
                if (value > 1) {
                    valid = false;
                } else {
                    new_val = (current & ~(1U << 31)) | ((uint32_t)value << 31);
                }
                break;
            default:
                valid = false;
                break;
        }

        if (!valid) {
            emit(-1);
        } else {
            *ctrl_reg = new_val;
            emitu(*ctrl_reg);
        }
    }

